"""因子抽象基类。"""
from __future__ import annotations
from abc import ABC, abstractmethod
from typing import TYPE_CHECKING

import numpy as np
import pandas as pd

if TYPE_CHECKING:
    from factors.inputs import FactorDataLoader

class BaseFactor(ABC):
    """选股因子基类。

    Attributes
    ----------
    name : 因子唯一标识名
    description : 因子描述
    """

    name: str = ""
    description: str = ""

    @abstractmethod
    def generate_signals(
        self,
        data: pd.DataFrame,
        constituents: dict[str, set[str]] | None = None,
    ) -> pd.DataFrame:
        """生成选股信号矩阵。

        Parameters
        ----------
        data : (date, symbol) MultiIndex 数据

        Returns
        -------
        pd.DataFrame，索引为 date，列为 symbol，值为因子信号
        """
        ...


class MinuteFactor(BaseFactor, ABC):
    """使用分钟行情生成日频截面信号的因子基类。

    分钟行情按自然月分块读取；每个信号日传给子类的数据只包含截至当日的
    ``minute_window_days`` 个交易日，避免未来数据泄漏。子类只需实现
    ``calculate_daily_factor``，最终仍返回普通的日频 ``date × symbol`` 信号。
    """

    minute_fields: tuple[str, ...] = ()
    minute_window_days: int = 1

    def __init__(
        self,
        minute_fields: list[str] | tuple[str, ...],
        minute_window_days: int = 1,
    ) -> None:
        fields = tuple(minute_fields)
        if not fields:
            raise ValueError("分钟因子必须声明至少一个 minute_fields 字段")
        if len(set(fields)) != len(fields):
            raise ValueError("minute_fields 不能包含重复字段")
        if (
            isinstance(minute_window_days, bool)
            or not isinstance(minute_window_days, (int, np.integer))
            or minute_window_days < 1
        ):
            raise ValueError("minute_window_days 必须为正整数")
        self.minute_fields = fields
        self.minute_window_days = int(minute_window_days)

    def generate_signals(
        self,
        data: pd.DataFrame,
        constituents: dict[str, set[str]] | None = None,
    ) -> pd.DataFrame:
        """分钟因子必须由 Runner 注入 FactorDataLoader 后计算。"""
        raise RuntimeError("分钟因子请通过 Runner 或 generate_minute_signals 运行")

    def generate_minute_signals(
        self,
        daily_data: pd.DataFrame,
        data_loader: FactorDataLoader,
    ) -> pd.DataFrame:
        """按月读取分钟数据，并逐交易日生成一个股票截面。"""
        if daily_data.empty:
            raise ValueError("分钟因子缺少日频股票池和中性化数据")
        if (
            not isinstance(daily_data.index, pd.MultiIndex)
            or daily_data.index.names[:2] != ["date", "symbol"]
        ):
            raise ValueError("日频输入必须使用 (date, symbol) MultiIndex")

        signal_dates = pd.DatetimeIndex(data_loader.trading_calendar).sort_values().unique()
        history_dates = pd.DatetimeIndex(data_loader.history_calendar).sort_values().unique()
        if signal_dates.empty:
            return pd.DataFrame(index=signal_dates)
        if history_dates.empty:
            raise ValueError("分钟因子缺少日频交易日历")

        if hasattr(self, '_day_cache'):
            self._day_cache.clear()

        all_symbols = pd.Index(
            daily_data.index.get_level_values("symbol").unique(),
            dtype="object",
        )
        date_values = daily_data.index.get_level_values("date")
        signals: list[pd.Series] = []

        for month in signal_dates.to_period("M").unique():
            output_dates = signal_dates[signal_dates.to_period("M") == month]
            first_position = int(history_dates.get_indexer([output_dates[0]])[0])
            if first_position < 0:
                raise ValueError(f"交易日历缺少信号日: {output_dates[0]:%Y-%m-%d}")
            read_start_position = first_position - self.minute_window_days + 1
            if read_start_position < 0:
                raise ValueError(
                    f"{output_dates[0]:%Y-%m-%d} 之前没有足够的"
                    f" {self.minute_window_days} 日分钟窗口"
                )

            if data_loader.constituents.empty:
                chunk_symbols = all_symbols
            else:
                member_slice = data_loader.constituents.reindex(
                    index=history_dates[read_start_position:history_dates.get_indexer([output_dates[-1]])[0] + 1],
                    columns=all_symbols,
                    fill_value=False,
                )
                chunk_symbols = member_slice.columns[member_slice.any(axis=0)]

            from factors.inputs import read_inputs
            minute_chunk = read_inputs(
                self.MINUTE_INPUTS,
                start=history_dates[read_start_position],
                end=output_dates[-1],
                symbols=chunk_symbols,
            ).rename_axis(index=["trade_time", "symbol"])
            if not minute_chunk.empty:
                times = minute_chunk.index.get_level_values('trade_time').normalize()
                tickers = minute_chunk.index.get_level_values('symbol')
                keys = pd.MultiIndex.from_arrays([times, tickers], names=['date', 'symbol'])
                valid = np.ones(len(keys), dtype=bool)
                if not data_loader.constituents.empty:
                    members = data_loader.constituents.stack(future_stack=True)
                    valid &= members.reindex(keys).fillna(False).to_numpy(dtype=bool)
                if not data_loader.security_status.empty:
                    excluded = data_loader.security_status.stack(future_stack=True)
                    valid &= ~excluded.reindex(keys).fillna(True).to_numpy(dtype=bool)
                minute_chunk = minute_chunk.loc[valid]
            if minute_chunk.empty:
                minute_by_date: dict[pd.Timestamp, pd.DataFrame] = {}
                empty_minute = minute_chunk
            else:
                minute_trade_dates = minute_chunk.index.get_level_values(
                    "trade_time"
                ).normalize()
                minute_by_date = {
                    pd.Timestamp(trade_date): frame
                    for trade_date, frame in minute_chunk.groupby(
                        minute_trade_dates,
                        sort=False,
                    )
                }
                empty_minute = minute_chunk.iloc[:0].copy()

            for trade_date in output_dates:
                position = int(history_dates.get_indexer([trade_date])[0])
                if position < self.minute_window_days - 1:
                    raise ValueError(
                        f"{trade_date:%Y-%m-%d} 之前没有足够的"
                        f" {self.minute_window_days} 日分钟窗口"
                    )
                window_dates = history_dates[
                    position - self.minute_window_days + 1 : position + 1
                ]
                window_parts = [
                    minute_by_date.get(pd.Timestamp(day), empty_minute)
                    for day in window_dates
                ]
                minute_window = pd.concat(window_parts).sort_index()
                minute_window.attrs["trade_dates"] = tuple(window_dates)

                if data_loader.constituents.empty:
                    symbols = chunk_symbols
                else:
                    membership = data_loader.constituents.reindex(
                        index=[trade_date],
                        columns=chunk_symbols,
                        fill_value=False,
                    ).iloc[0]
                    symbols = membership.index[membership]

                daily_history = daily_data.loc[date_values <= trade_date]
                signal = self.calculate_daily_factor(
                    trade_date=pd.Timestamp(trade_date),
                    symbols=list(symbols),
                    daily_data=daily_history,
                    minute_data=minute_window,
                )
                if not isinstance(signal, pd.Series):
                    raise TypeError("calculate_daily_factor 必须返回 pd.Series")
                if not signal.index.is_unique:
                    raise ValueError("分钟因子返回了重复股票代码")
                signal = signal.reindex(symbols)
                signal.name = pd.Timestamp(trade_date)
                signals.append(signal)

        result = pd.DataFrame(signals).reindex(signal_dates)
        result.index.name = "date"
        result.columns.name = "symbol"
        return result

    @abstractmethod
    def calculate_daily_factor(
        self,
        trade_date: pd.Timestamp,
        symbols: list[str],
        daily_data: pd.DataFrame,
        minute_data: pd.DataFrame,
    ) -> pd.Series:
        """将截至 ``trade_date`` 的分钟窗口降频为当日股票截面。"""
        ...


import re
def _create_formula_calculations():
    """Alpha表达式、公告时点财务快照与市场因子的共享公式。"""


    import math, re
    TOKEN = re.compile('\\s*(?:(\\d*\\.\\d+|\\d+\\.?\\d*(?:[eE][+-]?\\d+)?)|([A-Za-z_]\\w*)|(&&|\\|\\||==|!=|<=|>=|[()+*/^,?:<>!\\-]))')

    class FormulaError(ValueError):
        pass

    class Parser:

        def __init__(self, text):
            self.tokens = []
            pos = 0
            text = text.strip().rstrip(';').replace('−', '-').replace('–', '-').replace('×', '*').replace('**', '^').replace('./', '/').replace('.*', '*')
            text = re.sub('(?<![<>=!])=(?!=)', '==', text)
            text = re.sub('(?<!&)&(?!&)', '&&', text)
            text = re.sub('(?<!\\|)\\|(?!\\|)', '||', text)
            text = re.sub('\\bOR\\b', '||', text)
            while pos < len(text):
                m = TOKEN.match(text, pos)
                if not m:
                    raise FormulaError('unparsed ' + text[pos:pos + 35])
                self.tokens.append(('num', float(m[1])) if m[1] else ('name', m[2]) if m[2] else ('op', m[3]))
                pos = m.end()
            self.tokens.append(('eof', ''))
            self.i = 0

        def peek(self):
            return self.tokens[self.i][1]

        def take(self, val=None):
            token = self.tokens[self.i]
            if val is not None and token[1] != val:
                raise FormulaError(f'expected {val}, got {token}')
            self.i += 1
            return token

        def expr(self, minimum=0):
            (typ, val) = self.take()
            if val in ['+', '-', '!']:
                left = ('unary', val, self.expr(6))
            elif val == '(':
                left = self.expr()
                self.take(')')
            elif typ == 'num':
                left = ('num', val)
            elif typ == 'name':
                if self.peek() == '(':
                    self.take('(')
                    args = []
                    if self.peek() != ')':
                        while True:
                            args.append(self.expr())
                            if self.peek() != ',':
                                break
                            self.take(',')
                    self.take(')')
                    left = ('call', val.lower(), args)
                else:
                    left = ('var', val)
            else:
                raise FormulaError('bad atom ' + str((typ, val)))
            precedence = {'||': 1, '&&': 2, '==': 3, '!=': 3, '<': 3, '>': 3, '<=': 3, '>=': 3, '+': 4, '-': 4, '*': 5, '/': 5, '^': 6}
            while True:
                op = self.peek()
                if op == '?' and minimum <= 0:
                    self.take('?')
                    yes = self.expr()
                    self.take(':')
                    no = self.expr()
                    left = ('if', left, yes, no)
                    continue
                if op not in precedence or precedence[op] < minimum:
                    break
                self.take()
                right = self.expr(precedence[op] + (0 if op == '^' else 1))
                left = ('bin', op, left, right)
            return left

        def parse(self):
            node = self.expr()
            if self.tokens[self.i][0] != 'eof':
                raise FormulaError('trailing ' + str(self.tokens[self.i:]))
            return node

    def number(node):
        if node[0] == 'num':
            return node[1]
        if node[0] == 'unary' and node[1] in ['+', '-']:
            return number(node[2]) * (1 if node[1] == '+' else -1)
        if node[0] == 'bin' and node[1] in ['+', '-', '*', '/', '^']:
            (a, b) = (number(node[2]), number(node[3]))
            return {'+': lambda : a + b, '-': lambda : a - b, '*': lambda : a * b, '/': lambda : a / b, '^': lambda : a ** b}[node[1]]()
        raise FormulaError('period is not a fixed number')

    def inspect(node, kind):
        """Return minimum historical observations, operators, and input symbols."""
        ops = set()
        variables = set()
        recursive = []

        def period(n, allow_zero=False):
            v = math.floor(number(n))
            if v < (0 if allow_zero else 1):
                raise FormulaError('invalid period ' + str(v))
            return v

        def walk(n):
            tag = n[0]
            if tag == 'num':
                return 0
            if tag == 'var':
                v = n[1]
                variables.add(v)
                if v.upper() in ['O', 'H', 'L', 'C', 'V', 'A', 'P', 'MC', 'BO', 'BC', 'SW1', 'SW2', 'SW3']:
                    return 0
                if v.upper() in ['R', 'RET', 'HD', 'LD', 'TR']:
                    return 1
                if re.fullmatch('adv\\d+', v, re.I):
                    return int(v[3:]) - 1
                raise FormulaError('undefined variable ' + v)
            if tag == 'unary':
                return walk(n[2])
            if tag == 'bin':
                return max(walk(n[2]), walk(n[3]))
            if tag == 'if':
                return max(map(walk, n[1:]))
            (op, args) = (n[1], n[2])
            ops.add(op)
            if op in ['delay', 'delta']:
                if len(args) != 2:
                    raise FormulaError(op + ' arity')
                return walk(args[0]) + period(args[1], True)
            if op in ['abs', 'sign', 'log', 'rank', 'scale', 'signedpower', 'indneutralize']:
                if op in ['abs', 'sign', 'log', 'rank'] and len(args) != 1:
                    raise FormulaError(op + ' arity')
                if op in ['signedpower', 'indneutralize'] and len(args) != 2:
                    raise FormulaError(op + ' arity')
                if op == 'scale' and len(args) not in [1, 2]:
                    raise FormulaError('scale arity')
                return max(map(walk, args))
            rolling = ['sum', 'mean', 'std', 'stddev', 'ts_rank', 'tsrank', 'ts_min', 'tsmin', 'ts_max', 'tsmax', 'ts_argmax', 'ts_argmin', 'decay_linear', 'decaylinear', 'product', 'prod', 'count', 'highday', 'lowday']
            if kind == 101 and op in ['min', 'max']:
                if len(args) != 2:
                    raise FormulaError(op + ' arity')
                if args[1][0] == 'num' and args[1][1] >= 1:
                    return walk(args[0]) + period(args[1]) - 1
                return max(map(walk, args))
            if op in rolling:
                if len(args) != 2:
                    raise FormulaError(op + ' arity')
                return walk(args[0]) + period(args[1]) - 1
            if op in ['correlation', 'corr', 'covariance', 'coviance']:
                if len(args) != 3:
                    raise FormulaError(op + ' arity')
                return max(walk(args[0]), walk(args[1])) + period(args[2]) - 1
            if kind == 191 and op in ['max', 'min']:
                if len(args) != 2:
                    raise FormulaError(op + ' arity')
                if args[1][0] == 'num' and args[1][1] > 1:
                    raise FormulaError('MAX/MIN constant overload unconfirmed')
                return max(map(walk, args))
            if kind == 191 and op == 'sma':
                if len(args) != 3:
                    raise FormulaError('SMA needs N,M')
                nperiod = period(args[1])
                m = number(args[2])
                if not 0 < m <= nperiod:
                    raise FormulaError('SMA weight invalid')
                recursive.append(nperiod)
                return walk(args[0]) + nperiod - 1
            if kind == 191 and op == 'sumif':
                if len(args) != 3:
                    raise FormulaError('SUMIF needs X,N,condition')
                return max(walk(args[0]), walk(args[2])) + period(args[1]) - 1
            raise FormulaError('unconfirmed operator ' + op)
        span = walk(node) + 1
        return dict(observations=span, operators=sorted(ops), variables=sorted(variables), recursive_periods=recursive)

    import math
    import numpy as np
    import pandas as pd

    def evaluate_alpha(node, env, kind, *, constant_correlation_zero=False):
        template = env['C']

        def frame(x):
            return x if isinstance(x, pd.DataFrame) else pd.DataFrame(float(x), index=template.index, columns=template.columns)

        def safe(x):
            return frame(x).replace([np.inf, -np.inf], np.nan)

        def period(x):
            return int(math.floor(number(x)))

        def recursive(x, n, m):
            x = frame(x)
            out = np.full(x.shape, np.nan)
            for j in range(x.shape[1]):
                seed = []
                state = np.nan
                for (i, v) in enumerate(x.iloc[:, j].to_numpy(dtype=float)):
                    if not np.isfinite(v):
                        seed = []
                        state = np.nan
                        continue
                    if not np.isfinite(state):
                        seed.append(v)
                        if len(seed) == n:
                            state = float(np.mean(seed))
                    else:
                        state = (m * v + (n - m) * state) / n
                    out[i, j] = state
            return pd.DataFrame(out, index=x.index, columns=x.columns)

        def run(a):
            tag = a[0]
            if tag == 'num':
                return a[1]
            if tag == 'var':
                return env[a[1]]
            if tag == 'unary':
                x = frame(run(a[2]))
                return x if a[1] == '+' else -x if a[1] == '-' else (x == 0).astype(float).mask(x.isna())
            if tag == 'if':
                c = frame(run(a[1]))
                return frame(run(a[2])).where(c != 0, frame(run(a[3]))).mask(c.isna())
            if tag == 'bin':
                op = a[1]
                x = frame(run(a[2]))
                y = frame(run(a[3]))
                if op == '+':
                    return safe(x + y)
                if op == '-':
                    return safe(x - y)
                if op == '*':
                    return safe(x * y)
                if op == '/':
                    return safe(x / y.mask(y == 0))
                if op == '^':
                    return safe(x.pow(y))
                value = {'<': lambda : x < y, '>': lambda : x > y, '<=': lambda : x <= y, '>=': lambda : x >= y, '==': lambda : x == y, '!=': lambda : x != y, '&&': lambda : (x != 0) & (y != 0), '||': lambda : (x != 0) | (y != 0)}[op]()
                return value.astype(float).mask(x.isna() | y.isna())
            (op, args) = (a[1], a[2])
            x = frame(run(args[0]))
            if op == 'abs':
                return x.abs()
            if op == 'sign':
                return np.sign(x)
            if op == 'log':
                return np.log(x.where(x > 0))
            if op == 'rank':
                return x.where(env['_eligible']).rank(axis=1, method='average', pct=True)
            if op == 'scale':
                x = x.where(env['_eligible'])
                den = x.abs().sum(axis=1, min_count=1)
                return x.div(den.where(den != 0), axis=0) * (number(args[1]) if len(args) > 1 else 1.0)
            if op == 'signedpower':
                return safe(np.sign(x) * x.abs().pow(run(args[1])))
            if op == 'indneutralize':
                groups = run(args[1])
                valid = env['_eligible'] & groups.notna()
                out = x.where(valid).copy()
                for date in out.index:
                    values = out.loc[date]
                    out.loc[date] = values - values.groupby(groups.loc[date]).transform('mean')
                return out
            if op in ('max', 'min'):
                if args[1][0] == 'num' and args[1][1] >= (1 if kind == 101 else 2):
                    n = period(args[1])
                    return x.rolling(n, min_periods=n).max() if op == 'max' else x.rolling(n, min_periods=n).min()
                y = frame(run(args[1]))
                return safe(np.maximum(x, y) if op == 'max' else np.minimum(x, y)).mask(x.isna() | y.isna())
            if op in ('correlation', 'corr', 'covariance', 'coviance'):
                y = frame(run(args[1]))
                n = period(args[2])
                roll = x.rolling(n, min_periods=n)
                if op not in ('correlation', 'corr'):
                    return safe(roll.cov(y, ddof=1))
                value = safe(roll.corr(y))
                if constant_correlation_zero:
                    # Explicit LOCAL convention for Alpha101_096 only. A
                    # constant complete window has no correlation information.
                    # Missing data and incomplete windows remain missing.
                    other = y.rolling(n, min_periods=n)
                    complete = roll.count().eq(n) & other.count().eq(n)
                    constant = roll.max().eq(roll.min()) | other.max().eq(other.min())
                    value = value.mask(complete & constant, 0.0).clip(-1.0, 1.0)
                return value
            n = period(args[1])
            if op == 'delay':
                return x.shift(n)
            if op == 'delta':
                return x - x.shift(n)
            if op == 'sma':
                return recursive(x, n, number(args[2]))
            if op == 'sumif':
                cond = frame(run(args[2]))
                return x.where(cond != 0, 0).mask(cond.isna()).rolling(n, min_periods=n).sum()
            r = x.rolling(n, min_periods=n)
            if op in ('sum', 'count'):
                return r.sum()
            if op in ('mean', 'ma'):
                return r.mean()
            if op in ('std', 'stddev'):
                return r.std(ddof=1)
            if op in ('ts_min', 'tsmin'):
                return r.min()
            if op in ('ts_max', 'tsmax'):
                return r.max()
            if op in ('product', 'prod'):
                return r.apply(np.prod, raw=True)
            if op in ('ts_rank', 'tsrank'):
                return r.apply(lambda v: (np.sum(v < v[-1]) + (np.sum(v == v[-1]) + 1) / 2) / len(v), raw=True)
            if op in ('ts_argmax', 'ts_argmin', 'highday', 'lowday'):
                fn = np.argmax if op in ('ts_argmax', 'highday') else np.argmin
                return r.apply(lambda v: n - 1 - fn(v) if op in ('highday', 'lowday') else fn(v) + 1, raw=True)
            if op in ('decaylinear', 'decay_linear', 'wma'):
                w = 0.9 ** np.arange(n - 1, -1, -1) if op == 'wma' else np.arange(1, n + 1, dtype=float)
                return r.apply(lambda v: np.dot(v, w) / w.sum(), raw=True)
            raise ValueError(f'未实现Alpha算子: {op}')
        return safe(run(node))

    import ast
    from collections import defaultdict
    from dataloader import read_parquet_table

    def read_reports(inputs, *, end, symbols):
        grouped = defaultdict(list)
        for source in inputs.values():
            if source.announcement_columns:
                grouped[source.path].append(source)
        reports = {}
        for path, sources in grouped.items():
            source = sources[0]
            if any((x.announcement_columns, x.filters, x.report_period_column, x.symbol_column) !=
                   (source.announcement_columns, source.filters, source.report_period_column, source.symbol_column)
                   for x in sources):
                raise ValueError(f"同表财务输入契约冲突: {path}")
            # A contract may explicitly request report dates as metadata.  They
            # must not enter numeric conversion (which turns dates into ns ints).
            metadata = {source.symbol_column, source.report_period_column,
                        *source.announcement_columns, *(k for k, _ in source.filters)}
            fields = {x.field for x in sources} - metadata
            table = path.split('/')[-3]
            columns = sorted(fields | {source.symbol_column, source.report_period_column,
                                       *source.announcement_columns, *(k for k, _ in source.filters)})
            frame = read_parquet_table(path, columns, date_column=source.report_period_column,
                                       symbol_column=source.symbol_column, end=end, symbols=symbols)
            for key, expected in source.filters:
                frame = frame.loc[frame[key].astype('string').str.replace(r'\.0$', '', regex=True).eq(expected)].copy()
            for column in (source.report_period_column, *source.announcement_columns):
                frame[column] = pd.to_datetime(frame[column].astype('string').str.replace(r'\.0$', '', regex=True),
                                               format='mixed', errors='coerce')
            frame['_available'] = frame[source.announcement_columns[0]]
            for column in source.announcement_columns[1:]:
                frame['_available'] = frame['_available'].combine_first(frame[column])
            frame = frame.rename(columns={source.symbol_column: 'ts_code', source.report_period_column: 'end_date'})
            frame = frame.loc[frame._available.notna() & frame.end_date.notna() & frame.ts_code.notna()]
            frame = frame.loc[(frame._available <= pd.Timestamp(end)) &
                              frame.end_date.dt.strftime('%m-%d').isin(('03-31', '06-30', '09-30', '12-31'))]
            for column in fields:
                frame[column] = pd.to_numeric(frame[column], errors='coerce').replace([np.inf, -np.inf], np.nan)
            frame['_period'] = frame.end_date.dt.year * 4 + frame.end_date.dt.quarter - 1
            frame = frame[['ts_code', '_available', '_period', *sorted(fields)]].drop_duplicates()
            keys = ['ts_code', '_available', '_period']
            grouped = frame.groupby(keys, sort=False, dropna=False)
            for field in sorted(fields):
                # Ambiguity in EBIT must not erase an agreed revenue value
                # on the same report. Preserve only unanimously equal fields;
                # never choose an arbitrary duplicate financial version.
                conflict = grouped[field].transform('nunique', dropna=False).gt(1)
                frame.loc[conflict, field] = np.nan
            frame = frame.drop_duplicates(keys)
            reports[table] = frame.sort_values(['_available', '_period'])
        return reports

    def leaf_panels(spec, reports, dates, symbols, *, return_available=False):
        leaves = spec['leaves']
        tables = sorted({leaf[0] for leaf in leaves.values()})
        arrays = {name: np.full((len(dates), len(symbols)), np.nan) for name in leaves}
        availability = np.full((len(dates), len(symbols)), np.datetime64('NaT'), dtype='datetime64[ns]')
        by_table = {table: {str(k): v for (k, v) in reports[table].groupby('ts_code', sort=False)} for table in tables}
        for (j, symbol) in enumerate(symbols):
            events = defaultdict(list)
            for table in tables:
                for row in by_table[table].get(str(symbol), pd.DataFrame()).to_dict('records'):
                    effective = dates.searchsorted(row['_available'], side='right')
                    if effective < len(dates):
                        events[int(effective)].append((table, row))
            state = {table: {} for table in tables}
            points = []
            available_points = []
            values = {key: [] for key in leaves}
            for (pos, updates) in sorted(events.items()):
                for (table, row) in updates:
                    state[table][row['_period']] = row
                common = set.intersection(*(set(state[t]) for t in tables))
                if spec.get('annual'):
                    common = {q for q in common if q % 4 == 3}
                q = max(common) if common else None

                used_announcements = []

                def raw(table, field, period):
                    record = state[table].get(period, {})
                    if '_available' in record:
                        used_announcements.append(record['_available'])
                    return record.get(field, np.nan)

                def quarter(table, field, period):
                    current = raw(table, field, period)
                    return current if period % 4 == 0 else current - raw(table, field, period - 1)
                points.append(pos)
                for (key, (table, field, mode, lag)) in leaves.items():
                    if q is None:
                        value = np.nan
                    else:
                        anchor = q - lag
                        if mode in ('B', 'Y', 'QY'):
                            value = raw(table, field, anchor)
                        elif mode == 'Q':
                            value = quarter(table, field, anchor)
                        elif mode == 'T':
                            value = sum((quarter(table, field, anchor - k) for k in range(4)))
                        elif mode == 'AVG4':
                            value = (raw(table, field, anchor) + raw(table, field, anchor - 4)) / 2
                        else:
                            raise ValueError(mode)
                    values[key].append(value)
                available_points.append(max(used_announcements) if used_announcements else pd.NaT)
            if points:
                positions = np.searchsorted(points, np.arange(len(dates)), side='right') - 1
                known = positions >= 0
                # pandas.NaT cannot be cast directly by NumPy in all supported
                # versions. Preserve unknown announcement dates as datetime NaT.
                available_dates = pd.to_datetime(available_points).to_numpy(dtype='datetime64[ns]')
                availability[known, j] = available_dates[positions[known]]
                for key in leaves:
                    arrays[key][known, j] = np.asarray(values[key], dtype=float)[positions[known]]
        result = {key: pd.DataFrame(value, index=dates, columns=symbols) for (key, value) in arrays.items()}
        if return_available:
            return result, pd.DataFrame(availability, index=dates, columns=symbols)
        return result

    def evaluate_expression(expression, env):
        """Only explicit scalar arithmetic, positive log, abs and positive-root powers."""

        def run(node):
            if isinstance(node, ast.Expression):
                return run(node.body)
            if isinstance(node, ast.Name):
                return env[node.id]
            if isinstance(node, ast.Constant) and isinstance(node.value, (int, float)):
                return node.value
            if isinstance(node, ast.UnaryOp):
                return -run(node.operand) if isinstance(node.op, ast.USub) else run(node.operand)
            if isinstance(node, ast.BinOp):
                (a, b) = (run(node.left), run(node.right))
                if isinstance(node.op, ast.Add):
                    return a + b
                if isinstance(node.op, ast.Sub):
                    return a - b
                if isinstance(node.op, ast.Mult):
                    return a * b
                if isinstance(node.op, ast.Div):
                    return a / (b.where(b != 0) if isinstance(b, pd.DataFrame) else b if b else np.nan)
                if isinstance(node.op, ast.Pow):
                    return a.where(a > 0).pow(b) if isinstance(a, pd.DataFrame) and b % 1 else a ** b
            if isinstance(node, ast.Call) and isinstance(node.func, ast.Name):
                x = run(node.args[0])
                if node.func.id == 'abs':
                    return abs(x)
                if node.func.id == 'log':
                    return np.log(x.where(x > 0))
                if node.func.id == 'positive':
                    return x.where(x > 0)
            raise ValueError(ast.dump(node))
        return run(ast.parse(expression, mode='eval'))

    def calculate_financial(spec, data, inputs):
        dates = pd.DatetimeIndex(data.index.get_level_values('date').unique()).sort_values()
        symbols = data.index.get_level_values('symbol').unique().sort_values()
        reports = read_reports(inputs, end=dates.max(), symbols=list(symbols))
        env = leaf_panels(spec, reports, dates, symbols)
        if 'total_mv' in data:
            env['MC'] = data.total_mv.unstack('symbol').reindex(index=dates, columns=symbols).astype(float).where(lambda x: x > 0) * 10000
        value = evaluate_expression(spec['expression'], env)
        if spec.get('daily_lag'):
            value = value / value.shift(spec['daily_lag']).where(lambda x: x != 0) - 1
        if spec.get('rank'):
            eligible = data['is_member'].unstack('symbol').reindex(index=dates, columns=symbols).astype('boolean').fillna(False).astype(bool)
            for column in ('is_st', 'is_suspended'):
                eligible &= ~data[column].unstack('symbol').reindex(index=dates, columns=symbols).astype('boolean').fillna(False).astype(bool)
            value = value.where(eligible).rank(axis=1, method='average', pct=True)
        return value.replace([np.inf, -np.inf], np.nan).rename_axis(index='date', columns='symbol')

    import re

    def monthly(name, c):
        periods = c.index.to_period('M')
        axis = pd.period_range(periods.min(), periods.max(), freq='M')
        last = c.groupby(periods).last(skipna=False).reindex(axis)
        r = last / last.shift(1) - 1
        if name == 'osap_monthly_max_return_1m':
            value = (c / c.shift(1) - 1).groupby(periods).max().reindex(axis)
        elif name == 'osap_monthly_return_skew_1m':
            value = (c / c.shift(1) - 1).groupby(periods).skew().reindex(axis)
        elif name == 'osap_monthly_reversal_1m':
            value = r
        elif name.startswith('osap_'):
            m = re.search('_(\\d+)n(\\d+)m$', name)
            b = int(m[1]) - 1
            a = int(m[2])
            n = b - a + 1
            value = (1 + r.shift(a)).rolling(n, min_periods=n).apply(np.prod, raw=True) - 1
        else:
            m = re.search('_seas_(\\d+)_(\\d+)(an|na)_', name)
            a = int(m[1])
            b = int(m[2])
            duration = b - a + 1
            offset = 12 * a - 1
            selected = sum((r.shift(offset + 12 * j) for j in range(duration)))
            value = selected / duration if m[3] == 'an' else (r.shift(offset - 11).rolling(12 * duration, min_periods=12 * duration).sum() - selected) / (11 * duration)
        ends = axis.to_timestamp(how='end').normalize()
        out = np.full(c.shape, np.nan)
        positions = np.searchsorted(ends.to_numpy(), c.index.to_numpy(), side='left') - 1
        valid = positions >= 0
        out[valid] = value.to_numpy(dtype=float)[positions[valid]]
        return pd.DataFrame(out, index=c.index, columns=c.columns)

    def calculate_market(spec, x, eligible):
        name = spec['name']
        mean = lambda a, n: a.rolling(n, min_periods=n).mean()
        std = lambda a, n: a.rolling(n, min_periods=n).std(ddof=1)
        divide = lambda a, b: a / b.where(b != 0)
        if name.startswith('qlib_'):
            m = re.fullmatch('qlib_(close|open|high|low|vwap|volume)_lag(\\d+)_\\d+d', name)
            assert m, name
            column = {'close': 'close_hfq', 'open': 'open_hfq', 'high': 'high_hfq', 'low': 'low_hfq', 'volume': 'vol', 'vwap': 'P'}[m[1]]
            denominator = x['vol'] if m[1] == 'volume' else x['close_hfq']
            return divide(x[column].shift(int(m[2])), denominator)
        c = x.get('close_hfq')
        n = int(re.search('_(\\d+)d$', name)[1]) if re.search('_(\\d+)d$', name) else None
        if name.startswith(('osap_monthly', 'osap_mom', 'osap_int_mom', 'osap_l_rreversal', 'osap_m_rreversal', 'pyanomaly_crspm_seas')):
            return monthly(name, c)
        if name in ('osap_log_price_1d', 'tushare_log_unadjusted_price_1d'):
            return np.log(x['close'].where(x['close'] > 0))
        if name == 'osap_log_total_market_cap_1d':
            return np.log((x['total_mv'] * 10000).where(x['total_mv'] > 0))
        if name.startswith('jkp_r'):
            r = c / c.shift(1) - 1
            roll = r.rolling(21, min_periods=21)
            if 'rvol_' in name:
                return roll.std(ddof=1)
            if 'rmax1' in name:
                return roll.max()
            if 'rskew' in name:
                return roll.skew()
            top = roll.apply(lambda v: np.partition(v, -5)[-5:].mean(), raw=True)
            return divide(top, roll.std(ddof=1)) if '_rvol_' in name else top
        if name.startswith('tushare_return_std_'):
            return std(c / c.shift(1) - 1, n)
        if name.startswith('tushare_return_'):
            return c / c.shift(n) - 1
        if name.startswith('tushare_nav_range_'):
            return divide(c.rolling(n, min_periods=n).max(), c.rolling(n, min_periods=n).min())
        if name.startswith('tushare_total_share_turnover_'):
            t = divide(x['vol'] * 100, x['total_share'] * 10000)
            return std(t, n) if '_std_' in name else mean(t, n)
        if name == 'rqdata_turnover_rate_local_1d':
            return divide(x['vol'] * 100, x['float_share'] * 10000)
        if name.startswith('datayes_tvstd'):
            return (x['amount'] * 1000).rolling(n, min_periods=n).std(ddof=1)
        if name.startswith('datayes_vstd'):
            return (x['vol'] * 100).rolling(n, min_periods=n).std(ddof=1)
        if name.startswith(('datayes_variance', 'datayes_gainvariance', 'datayes_lossvariance', 'datayes_gainlossvarianceratio', 'datayes_kurtosis')):
            r = c / c.shift(1) - 1
            roll = r.rolling(n, min_periods=n)
            if name.startswith('datayes_variance'):
                return roll.var(ddof=1)
            if name.startswith('datayes_kurtosis'):
                return roll.kurt()

            def conditional(values, positive):
                selected = values[values > 0] if positive else values[values < 0]
                return np.var(selected, ddof=1) if len(selected) >= 2 else np.nan
            if name.startswith('datayes_gainlossvarianceratio'):
                return divide(roll.apply(lambda v: conditional(v, True), raw=True), roll.apply(lambda v: conditional(v, False), raw=True))
            positive = name.startswith('datayes_gainvariance')
            return roll.apply(lambda v: conditional(v, positive), raw=True)
        if name.startswith('tushare_total_turnover_'):
            m = re.search('_(\\d+)_(\\d+)d$', name)
            (a, b) = (int(m[1]), int(m[2]))
            t = divide(x['vol'] * 100, x['total_share'] * 10000)
            op = std if '_std_' in name else mean
            return divide(op(t, a), op(t, b)) - 1
        if name.startswith('tushare_negative_log') or name == 'tushare_nonlinear_size_residual_1d':
            shares = x['float_share'] if '_float_' in name else x['total_share']
            size = shares * 10000 * x['close'] / 1000000.0
            s = -np.log(size.where(size > 0))
            if name != 'tushare_nonlinear_size_residual_1d':
                return s
            s = s.where(eligible)
            out = s.copy() * np.nan
            for (date, row) in s.iterrows():
                valid = row.dropna()
                if len(valid) < 3 or valid.std() == 0:
                    continue
                design = np.column_stack([np.ones(len(valid)), valid.to_numpy()])
                y = valid.to_numpy() ** 3
                out.loc[date, valid.index] = y - design @ np.linalg.lstsq(design, y, rcond=None)[0]
            return out
        if name.startswith(('tushare_amount_mean', 'datayes_amount_mean')):
            return mean(x['amount'] * 1000, n)
        if name == 'tushare_close_mean_20d':
            return mean(c, 20)
        if name == 'tushare_abs_return_amount_ratio_20d':
            return divide((c / c.shift(1) - 1).abs().rolling(20, min_periods=20).sum(), (x['amount'] * 1000).rolling(20, min_periods=20).sum())
        if name.startswith('datayes_float_share_turnover_mean_'):
            return mean(divide(x['vol'] * 100, x['float_share'] * 10000), n)
        if name.startswith('datayes_float_turnover_mean_difference_'):
            m = re.search('difference_(\\d+)_(\\d+)_', name)
            t = divide(x['vol'] * 100, x['float_share'] * 10000)
            return mean(t, int(m[1])) - mean(t, int(m[2]))
        if name in ('datayes_float_market_cap_1d', 'datayes_total_market_cap_1d'):
            return x['circ_mv' if '_float_' in name else 'total_mv'] * 10000
        if name == 'datayes_log_float_market_cap_1d':
            return np.log((x['circ_mv'] * 10000).where(x['circ_mv'] > 0))
        if name.startswith('datayes_volume_roc_percent_'):
            return 100 * (divide(x['vol'], x['vol'].shift(n)) - 1)
        if name.startswith('datayes_cci_'):
            tp = (x['high_hfq'] + x['low_hfq'] + c) / 3
            mad = tp.rolling(n, min_periods=n).apply(lambda v: np.abs(v - v.mean()).mean(), raw=True)
            return divide(tp - mean(tp, n), 0.015 * mad)
        if name.startswith(('datayes_close_mean_qfq_', 'datayes_bias_', 'datayes_ma_to_close_')):
            adjusted = x['close'] * x['adj_factor']
            m = mean(adjusted, n)
            if name.startswith('datayes_bias_'):
                return 100 * (divide(adjusted, m) - 1)
            if name.startswith('datayes_ma_to_close_'):
                return divide(m, adjusted)
            return divide(m, x['adj_factor'])
        raise ValueError(f'缺少市场因子定义: {name}')

    from types import SimpleNamespace
    return SimpleNamespace(**locals())


def _create_technical_calculations():
    """本地数值核适配：真实输入连续区段、固定初始化、单列输出与日期对齐。"""

    import ctypes
    from functools import lru_cache
    from types import SimpleNamespace as _KernelNamespace
    import inspect
    from pathlib import Path
    import numpy as np
    import pandas as pd

    DP=ctypes.POINTER(ctypes.c_double);IP=ctypes.POINTER(ctypes.c_int)
    @lru_cache(None)
    def native_library():return ctypes.CDLL(str(Path(__file__).with_name('_numeric_native.so')))
    @lru_cache(None)
    def kernel(name):
        """按配方标识延迟初始化本文件中的独立数值命名空间。"""
        return _KERNEL_FACTORIES[name]()

    def native(spec,x):
        n=len(x);result=np.full(n,np.nan)
        if n<=spec.get('warmup',0):return result
        function=getattr(native_library(),spec['root_function']);keep=[]
        if spec['engine']=='tulip':
            arrays=[np.ascontiguousarray(x['close' if k=='real' else k],dtype=float) for k in spec['required_inputs']]
            pointers=(DP*len(arrays))(*(a.ctypes.data_as(DP) for a in arrays))
            options=np.asarray(spec['options'] or [0.],dtype=float)
            output=[np.zeros(n,dtype=float) for _ in spec['outputs']]
            outputs=(DP*len(output))(*(a.ctypes.data_as(DP) for a in output))
            function.argtypes=[ctypes.c_int,ctypes.POINTER(DP),DP,ctypes.POINTER(DP)];function.restype=ctypes.c_int
            rc=function(n,pointers,options.ctypes.data_as(DP),outputs)
            if rc:raise ValueError(f"{spec['root_function']}返回错误{rc}")
            start=spec['warmup'];result[start:]=output[spec['output_index']][:n-start]
            return result
        mapping={'inReal':'close','inReal0':'close','inReal1':'benchmark','inOpen':'open','inHigh':'high','inLow':'low','inClose':'close','inVolume':'volume'}
        values=[];types=[];output=[];begin=ctypes.c_int();count=ctypes.c_int();option=iter(spec['options'])
        for name,typ in spec['abi']:
            if name in ('startIdx','endIdx'):values.append(0 if name=='startIdx' else n-1);types.append(ctypes.c_int)
            elif name.startswith('optIn'):
                value=next(option);values.append(float(value) if typ=='double' else int(value));types.append(ctypes.c_double if typ=='double' else ctypes.c_int)
            elif name in ('outBegIdx','outNBElement','outNbElement'):
                values.append(ctypes.byref(begin if name=='outBegIdx' else count));types.append(IP)
            elif name.startswith('in'):
                a=np.ascontiguousarray(x[mapping[name]],dtype=float);keep.append(a);values.append(a.ctypes.data_as(DP));types.append(DP)
            else:
                a=np.zeros(n,dtype=float if typ=='double' else np.int32);keep.append(a);output.append(a);pointer=DP if typ=='double' else IP;values.append(a.ctypes.data_as(pointer));types.append(pointer)
        function.argtypes=types;function.restype=ctypes.c_int
        rc=function(*values)
        if rc:raise ValueError(f"{spec['root_function']}返回错误{rc}")
        result[begin.value:begin.value+count.value]=output[spec['output_index']][:count.value]
        return result

    def scalar(spec,x):
        engine=spec['engine'];params=spec.get('parameters',{})
        if engine in ('talib','tulip'):return native(spec,x)
        if engine=='ta':
            module=kernel('ta_'+spec['module']);cls=getattr(module,spec['class'])
            kwargs={name:x[name] for name in inspect.signature(cls).parameters if name in x}
            kwargs.update(params);out=getattr(cls(**kwargs),spec['getter'])()
        elif engine=='finta':
            module=kernel(spec.get('kernel','finta_scalar'));out=getattr(module.TA,spec['root_function'].split('.')[-1])(x.copy(),**params)
        elif engine=='stockstats':
            module=kernel(spec.get('kernel','stockstats_scalar'));return np.asarray(module.StockDataFrame.retype(x.copy())[params['column']],dtype=float)
        elif engine in ('ptac','pyti','simple','python'):
            module=kernel(spec['kernel']);fn=getattr(module,spec['root_function'])
            if engine=='simple':
                local={k:x[k] for k in x}
                # The shared kernel binds C for other branches; a volume-only row
                # neither reads nor validates an extra close input.
                local.setdefault('close',pd.Series(np.nan,index=x.index,dtype=float))
                out=fn(x=local,**params)
            else:
                kwargs={}
                for name in spec.get('required_inputs',[]):
                    mapped={'open_':'open','data':'close','close_data':'close','high_data':'high','low_data':'low','volume_data':'volume'}.get(name,name)
                    kwargs[name]=x[mapped].to_numpy(dtype=float).copy() if engine=='pyti' else x[mapped].copy()
                kwargs.update(spec.get('supplied_parameters',{}));out=fn(**kwargs)
        else:raise ValueError(engine)
        if isinstance(out,tuple):out=out[0]
        if out is None:
            # Appendix kernels use None specifically when verify_series determines
            # that their initialization history is too short (R3).
            return np.full(len(x),np.nan)
        if isinstance(out,pd.DataFrame):
            label=spec.get('output_label')
            if label and str(out.columns[spec['output_index']])!=label:raise ValueError(f'输出列不匹配: {label}, {list(out.columns)}')
            out=out.iloc[:,spec['output_index']]
        if isinstance(out,pd.Series) and isinstance(out.index,pd.DatetimeIndex):
            # Some kernels omit their warm-up dates rather than returning explicit
            # NaNs (for example FinTA DYMI). Align actual labels, never shift values.
            out=out.reindex(x.index)
        return np.asarray(out,dtype=float)

    def seeded_ema(x,n):
        out=pd.Series(np.nan,index=x.index,dtype=float);state=np.nan;seed=[]
        for i,v in enumerate(x):
            if not np.isfinite(v):seed=[];state=np.nan;continue
            if not np.isfinite(state):
                seed.append(v)
                if len(seed)==n:state=np.mean(seed)
            else:state+=2/(n+1)*(v-state)
            out.iloc[i]=state
        return out

    def simple(spec,x):
        c=x['close'];name=spec['name'];n=spec.get('period',14)
        mean=lambda a,k:a.rolling(k,min_periods=k).mean()
        mid=lambda k:(c.rolling(k,min_periods=k).max()+c.rolling(k,min_periods=k).min())/2
        if name.startswith('btalib_first_seed'):return c.ewm(span=30,adjust=False).mean()
        if name.startswith('btalib_linearreg_intercept'):
            xx=np.arange(1,15,dtype=float);zz=xx-xx.mean()
            return c.rolling(14,min_periods=14).apply(lambda v:v.mean()-np.dot(zz,v)/np.dot(zz,zz)*xx.mean(),raw=True)
        if name.startswith('btalib_'):
            fast=seeded_ema(c,12);slow=seeded_ema(c,26);d=100*(fast/slow-1) if 'ppo' in name else fast-slow
            signal=seeded_ema(d,9)
            return signal if '_signal_' in name else d-signal if '_histogram_' in name else d
        if name.startswith('pyti_tenkansen'):return mid(9)
        if name.startswith('pyti_kijunsen'):return mid(26)
        if name.startswith('pyti_senkou_a'):return ((mid(9)+mid(26))/2).shift(26)
        if name.startswith('pyti_senkou_b'):return mid(52).shift(26)
        if name.startswith(('pyti_buying_pressure','pyti_ultimate')):
            prev=c.shift(1);bp=c-np.minimum(x['low'],prev)
            tr=pd.concat([x['high']-x['low'],(x['high']-prev).abs(),(x['low']-prev).abs()],axis=1).max(axis=1,skipna=False)
            ratio=lambda k:bp.rolling(k,min_periods=k).sum()/tr.rolling(k,min_periods=k).sum().where(lambda y:y!=0)
            return 100*(4*ratio(7)+2*ratio(14)+ratio(28))/7 if name.startswith('pyti_ultimate') else ratio(n)
        if name=='ptac_cti_12d':
            xx=np.arange(12,dtype=float)
            return c.rolling(12,min_periods=12).apply(lambda v:np.corrcoef(v,xx)[0,1] if np.std(v)>0 else np.nan,raw=True)
        raise ValueError(f'缺少明确定义: {name}')

    def calculate(spec,panels):
        index=next(iter(panels.values())).index;columns=next(iter(panels.values())).columns
        out=pd.DataFrame(np.nan,index=index,columns=columns)
        minimum=spec.get('minimum',1);gate=spec.get('gate_bars',1)
        if spec['engine']=='pyti':
            minimum=max([minimum,*[int(v) for key,v in spec.get('parameters',{}).items()
                                  if 'period' in key and isinstance(v,(int,float)) and v>0]])
        if spec['name']=='stockstats_ftr_9d':minimum=max(minimum,9)
        if spec['name']=='pyti_double_smoothed_stochastic_14d':
            # The first rolling range shortens the input by period-1 before the
            # first EMA validates its own period-sized seed.
            minimum=max(minimum,2*spec['parameters']['period']-1)
        for symbol in columns:
            x=pd.DataFrame({key:value[symbol] for key,value in panels.items()})
            valid=np.isfinite(x.to_numpy(dtype=float)).all(axis=1)
            edges=np.diff(np.r_[False,valid,False].astype(int));starts=np.flatnonzero(edges==1);ends=np.flatnonzero(edges==-1)
            for start,end in zip(starts,ends):
                if end-start<max(minimum,gate):continue
                segment=x.iloc[start:end].copy()
                with np.errstate(all='ignore'):
                    value=simple(spec,segment) if spec['engine']=='explicit' else scalar(spec,segment)
                value=np.asarray(value,dtype=float)
                if value.shape!=(end-start,):raise ValueError(f"输出长度错误 {spec['name']}: {value.shape}")
                value[:gate-1]=np.nan;value[~np.isfinite(value)]=np.nan
                out.iloc[start:end,out.columns.get_loc(symbol)]=value
        return out


    # Each factory isolates the original numerical source and initializes only on demand.

    def _build_finta_scalar():
        from functools import wraps
        import pandas as pd
        import numpy as np
        from pandas import DataFrame, Series

        class TA:
            __version__ = '1.3'

            @classmethod
            def SMA(cls, ohlc: DataFrame, period: int=41, column: str='close') -> Series:
                return pd.Series(ohlc[column].rolling(window=period).mean(), name='{0} period SMA'.format(period))

            @classmethod
            def SMM(cls, ohlc: DataFrame, period: int=9, column: str='close') -> Series:
                return pd.Series(ohlc[column].rolling(window=period).median(), name='{0} period SMM'.format(period))

            @classmethod
            def SSMA(cls, ohlc: DataFrame, period: int=9, column: str='close', adjust: bool=True) -> Series:
                return pd.Series(ohlc[column].ewm(ignore_na=False, alpha=1.0 / period, min_periods=0, adjust=adjust).mean(), name='{0} period SSMA'.format(period))

            @classmethod
            def EMA(cls, ohlc: DataFrame, period: int=9, column: str='close', adjust: bool=True) -> Series:
                return pd.Series(ohlc[column].ewm(span=period, adjust=adjust).mean(), name='{0} period EMA'.format(period))

            @classmethod
            def DEMA(cls, ohlc: DataFrame, period: int=9, column: str='close', adjust: bool=True) -> Series:
                DEMA = 2 * cls.EMA(ohlc, period) - cls.EMA(ohlc, period).ewm(span=period, adjust=adjust).mean()
                return pd.Series(DEMA, name='{0} period DEMA'.format(period))

            @classmethod
            def TEMA(cls, ohlc: DataFrame, period: int=9, adjust: bool=True) -> Series:
                triple_ema = 3 * cls.EMA(ohlc, period)
                ema_ema_ema = cls.EMA(ohlc, period).ewm(ignore_na=False, span=period, adjust=adjust).mean().ewm(ignore_na=False, span=period, adjust=adjust).mean()
                TEMA = triple_ema - 3 * cls.EMA(ohlc, period).ewm(span=period, adjust=adjust).mean() + ema_ema_ema
                return pd.Series(TEMA, name='{0} period TEMA'.format(period))

            @classmethod
            def TRIMA(cls, ohlc: DataFrame, period: int=18) -> Series:
                SMA = cls.SMA(ohlc, period).rolling(window=period).sum()
                return pd.Series(SMA / period, name='{0} period TRIMA'.format(period))

            @classmethod
            def TRIX(cls, ohlc: DataFrame, period: int=20, column: str='close', adjust: bool=True) -> Series:
                data = ohlc[column]

                def _ema(data, period, adjust):
                    return pd.Series(data.ewm(span=period, adjust=adjust).mean())
                m = _ema(_ema(_ema(data, period, adjust), period, adjust), period, adjust)
                return pd.Series(100 * (m.diff() / m), name='{0} period TRIX'.format(period))

            @classmethod
            def VAMA(cls, ohlcv: DataFrame, period: int=8, column: str='close') -> Series:
                vp = ohlcv['volume'] * ohlcv[column]
                volsum = ohlcv['volume'].rolling(window=period).mean()
                volRatio = pd.Series(vp / volsum, name='VAMA')
                cumSum = (volRatio * ohlcv[column]).rolling(window=period).sum()
                cumDiv = volRatio.rolling(window=period).sum()
                return pd.Series(cumSum / cumDiv, name='{0} period VAMA'.format(period))

            @classmethod
            def ER(cls, ohlc: DataFrame, period: int=10, column: str='close') -> Series:
                change = ohlc[column].diff(period).abs()
                volatility = ohlc[column].diff().abs().rolling(window=period).sum()
                return pd.Series(change / volatility, name='{0} period ER'.format(period))

            @classmethod
            def KAMA(cls, ohlc: DataFrame, er: int=10, ema_fast: int=2, ema_slow: int=30, period: int=20, column: str='close') -> Series:
                # A complete flat-price window has zero movement and zero
                # variation: use the explicit no-trend ER=0 convention here.
                # Keep genuine missing inputs/warm-up missing; never fill the
                # factor's output or alter other indicators' ER definitions.
                change = ohlc[column].diff(er).abs()
                variation = ohlc[column].diff().abs().rolling(er, min_periods=er).sum()
                efficiency = cls.ER(ohlc, er)
                efficiency = efficiency.mask(variation.eq(0) & change.eq(0), 0.0)
                fast_alpha = 2 / (ema_fast + 1)
                slow_alpha = 2 / (ema_slow + 1)
                sc = pd.Series((efficiency * (fast_alpha - slow_alpha) + slow_alpha) ** 2, name='smoothing_constant')
                sma = pd.Series(ohlc[column].rolling(period).mean(), name='SMA')
                kama = []
                state = np.nan
                for (s, ma, price) in zip(sc.items(), sma.shift().items(), ohlc[column].items()):
                    if not np.isfinite(s[1]) or not np.isfinite(price[1]):
                        state = np.nan
                    elif np.isfinite(state):
                        state = state + s[1] * (price[1] - state)
                    elif np.isfinite(ma[1]):
                        # Same prior-period SMA seed as the original FinTA
                        # recurrence; reinitialize only from a valid seed.
                        state = ma[1] + s[1] * (price[1] - ma[1])
                    kama.append(state)
                return pd.Series(kama, index=sma.index, name='{0} period KAMA.'.format(period))

            @classmethod
            def ZLEMA(cls, ohlc: DataFrame, period: int=26, adjust: bool=True, column: str='close') -> Series:
                lag = (period - 1) / 2
                ema = pd.Series(ohlc[column] + ohlc[column].diff(lag), name='{0} period ZLEMA.'.format(period))
                zlema = pd.Series(ema.ewm(span=period, adjust=adjust).mean(), name='{0} period ZLEMA'.format(period))
                return zlema

            @classmethod
            def WMA(cls, ohlc: DataFrame, period: int=9, column: str='close') -> Series:
                d = period * (period + 1) / 2
                weights = np.arange(1, period + 1)

                def linear(w):

                    def _compute(x):
                        return (w * x).sum() / d
                    return _compute
                _close = ohlc[column].rolling(period, min_periods=period)
                wma = _close.apply(linear(weights), raw=True)
                return pd.Series(wma, name='{0} period WMA.'.format(period))

            @classmethod
            def HMA(cls, ohlc: DataFrame, period: int=16) -> Series:
                import math
                half_length = int(period / 2)
                sqrt_length = int(math.sqrt(period))
                wmaf = cls.WMA(ohlc, period=half_length)
                wmas = cls.WMA(ohlc, period=period)
                ohlc['deltawma'] = 2 * wmaf - wmas
                hma = cls.WMA(ohlc, column='deltawma', period=sqrt_length)
                return pd.Series(hma, name='{0} period HMA.'.format(period))

            @classmethod
            def EVWMA(cls, ohlcv: DataFrame, period: int=20) -> Series:
                vol_sum = ohlcv['volume'].rolling(window=period).sum()
                x = (vol_sum - ohlcv['volume']) / vol_sum
                y = ohlcv['volume'] * ohlcv['close'] / vol_sum
                evwma = [0]
                for (x, y) in zip(x.fillna(0).items(), y.items()):
                    if x[1] == 0 or y[1] == 0:
                        evwma.append(0)
                    else:
                        evwma.append(evwma[-1] * x[1] + y[1])
                return pd.Series(evwma[1:], index=ohlcv.index, name='{0} period EVWMA.'.format(period))

            @classmethod
            def VWAP(cls, ohlcv: DataFrame) -> Series:
                return pd.Series((ohlcv['volume'] * cls.TP(ohlcv)).cumsum() / ohlcv['volume'].cumsum(), name='VWAP.')

            @classmethod
            def SMMA(cls, ohlc: DataFrame, period: int=42, column: str='close', adjust: bool=True) -> Series:
                return pd.Series(ohlc[column].ewm(alpha=1 / period, adjust=adjust).mean(), name='SMMA')

            @classmethod
            def FRAMA(cls, ohlc: DataFrame, period: int=16, batch: int=10) -> Series:
                assert period % 2 == 0, print('FRAMA period must be even')
                c = ohlc.close.copy()
                window = batch * 2
                hh = c.rolling(batch).max()
                ll = c.rolling(batch).min()
                n1 = (hh - ll) / batch
                n2 = n1.shift(batch)
                hh2 = c.rolling(window).max()
                ll2 = c.rolling(window).min()
                n3 = (hh2 - ll2) / window
                D = (np.log(n1 + n2) - np.log(n3)) / np.log(2)
                alp = np.exp(-4.6 * (D - 1))
                # A complete flat window has no geometric dimension estimate;
                # explicitly follow its sole observed price (alpha=1).
                alp = alp.mask(n3.eq(0) & (n1 + n2).eq(0), 1.0)
                alp = np.clip(alp, 0.01, 1).values
                filt = c.values
                for (i, x) in enumerate(alp):
                    cl = c.values[i]
                    if i < window:
                        continue
                    filt[i] = cl * x + (1 - x) * filt[i - 1]
                return pd.Series(filt, index=ohlc.index, name='{0} period FRAMA.'.format(period))

            @classmethod
            def ROC(cls, ohlc: DataFrame, period: int=12, column: str='close') -> Series:
                return pd.Series(ohlc[column].diff(period) / ohlc[column].shift(period) * 100, name='ROC')

            @classmethod
            def RSI(cls, ohlc: DataFrame, period: int=14, column: str='close', adjust: bool=True) -> Series:
                delta = ohlc[column].diff()
                (up, down) = (delta.copy(), delta.copy())
                up[up < 0] = 0
                down[down > 0] = 0
                _gain = up.ewm(alpha=1.0 / period, adjust=adjust).mean()
                _loss = down.abs().ewm(alpha=1.0 / period, adjust=adjust).mean()
                RS = _gain / _loss
                return pd.Series(100 - 100 / (1 + RS), name='{0} period RSI'.format(period))

            @classmethod
            def IFT_RSI(cls, ohlc: DataFrame, column: str='close', rsi_period: int=5, wma_period: int=9) -> Series:
                v1 = pd.Series(0.1 * (cls.RSI(ohlc, rsi_period) - 50), name='v1')
                d = wma_period * (wma_period + 1) / 2
                weights = np.arange(1, wma_period + 1)

                def linear(w):

                    def _compute(x):
                        return (w * x).sum() / d
                    return _compute
                _wma = v1.rolling(wma_period, min_periods=wma_period)
                v2 = _wma.apply(linear(weights), raw=True)
                ift = pd.Series((v2 ** 2 - 1) / (v2 ** 2 + 1), name='IFT_RSI')
                return ift

            @classmethod
            def DYMI(cls, ohlc: DataFrame, column: str='close', adjust: bool=True) -> Series:

                def _get_time(close):
                    sd = close.rolling(5).std()
                    asd = sd.rolling(10).mean()
                    v = sd / asd
                    t = 14 / v.round()
                    t[t.isna()] = 0
                    t = t.map(lambda x: int(min(max(x, 5), 30)))
                    return t

                # Same finite local RSI slices and pandas EWM recurrence as
                # the published method, without rebuilding a DataFrame and
                # two pandas EWM objects for every historical observation.
                periods = _get_time(ohlc[column]).to_numpy(dtype=int)
                close = ohlc[column].to_numpy(dtype=float)
                result = np.full(max(0, len(close) - 14), np.nan)
                for index in range(14, len(close)):
                    length = int(periods[index])
                    changes = np.diff(close[max(0, index - length):index]).tolist()
                    if not changes:
                        continue
                    gain = max(changes[0], 0.0)
                    loss = max(-changes[0], 0.0)
                    alpha = 1.0 / length
                    old_weight = 1.0
                    for change in changes[1:]:
                        up, down = max(change, 0.0), max(-change, 0.0)
                        old_weight *= 1.0 - alpha
                        new_weight = 1.0 if adjust else alpha
                        if gain != up:
                            gain = (old_weight * gain + new_weight * up) / (old_weight + new_weight)
                        if loss != down:
                            loss = (old_weight * loss + new_weight * down) / (old_weight + new_weight)
                        old_weight = old_weight + new_weight if adjust else 1.0
                    result[index - 14] = (100.0 if gain > 0 else np.nan) if loss == 0 else 100.0 - 100.0 / (1.0 + gain / loss)
                return pd.Series(result, index=ohlc.index[14:])

            @classmethod
            def TR(cls, ohlc: DataFrame) -> Series:
                TR1 = pd.Series(ohlc['high'] - ohlc['low']).abs()
                TR2 = pd.Series(ohlc['high'] - ohlc['close'].shift()).abs()
                TR3 = pd.Series(ohlc['close'].shift() - ohlc['low']).abs()
                _TR = pd.concat([TR1, TR2, TR3], axis=1)
                _TR['TR'] = _TR.max(axis=1)
                return pd.Series(_TR['TR'], name='TR')

            @classmethod
            def ATR(cls, ohlc: DataFrame, period: int=14) -> Series:
                TR = cls.TR(ohlc)
                return pd.Series(TR.rolling(center=False, window=period).mean(), name='{0} period ATR'.format(period))

            @classmethod
            def BBANDS(cls, ohlc: DataFrame, period: int=20, MA: Series=None, column: str='close', std_multiplier: float=2) -> DataFrame:
                std = ohlc[column].rolling(window=period).std()
                if not isinstance(MA, pd.core.series.Series):
                    middle_band = pd.Series(cls.SMA(ohlc, period), name='BB_MIDDLE')
                else:
                    middle_band = pd.Series(MA, name='BB_MIDDLE')
                upper_bb = pd.Series(middle_band + std_multiplier * std, name='BB_UPPER')
                lower_bb = pd.Series(middle_band - std_multiplier * std, name='BB_LOWER')
                return pd.concat([upper_bb, middle_band, lower_bb], axis=1)

            @classmethod
            def BBWIDTH(cls, ohlc: DataFrame, period: int=20, MA: Series=None, column: str='close') -> Series:
                BB = TA.BBANDS(ohlc, period, MA, column)
                return pd.Series((BB['BB_UPPER'] - BB['BB_LOWER']) / BB['BB_MIDDLE'], name='{0} period BBWITH'.format(period))

            @classmethod
            def PERCENT_B(cls, ohlc: DataFrame, period: int=20, MA: Series=None, column: str='close') -> Series:
                BB = TA.BBANDS(ohlc, period, MA, column)
                percent_b = pd.Series((ohlc['close'] - BB['BB_LOWER']) / (BB['BB_UPPER'] - BB['BB_LOWER']), name='%b')
                return percent_b

            @classmethod
            def KC(cls, ohlc: DataFrame, period: int=20, atr_period: int=10, MA: Series=None, kc_mult: float=2) -> DataFrame:
                if not isinstance(MA, pd.core.series.Series):
                    middle = pd.Series(cls.EMA(ohlc, period), name='KC_MIDDLE')
                else:
                    middle = pd.Series(MA, name='KC_MIDDLE')
                up = pd.Series(middle + kc_mult * cls.ATR(ohlc, atr_period), name='KC_UPPER')
                down = pd.Series(middle - kc_mult * cls.ATR(ohlc, atr_period), name='KC_LOWER')
                return pd.concat([up, down], axis=1)

            @classmethod
            def DMI(cls, ohlc: DataFrame, period: int=14, adjust: bool=True) -> DataFrame:
                ohlc['up_move'] = ohlc['high'].diff()
                ohlc['down_move'] = -ohlc['low'].diff()

                def _dmp(row):
                    if row['up_move'] > row['down_move'] and row['up_move'] > 0:
                        return row['up_move']
                    else:
                        return 0

                def _dmn(row):
                    if row['down_move'] > row['up_move'] and row['down_move'] > 0:
                        return row['down_move']
                    else:
                        return 0
                ohlc['plus'] = ohlc.apply(_dmp, axis=1)
                ohlc['minus'] = ohlc.apply(_dmn, axis=1)
                diplus = pd.Series(100 * (ohlc['plus'] / cls.ATR(ohlc, period)).ewm(alpha=1 / period, adjust=adjust).mean(), name='DI+')
                diminus = pd.Series(100 * (ohlc['minus'] / cls.ATR(ohlc, period)).ewm(alpha=1 / period, adjust=adjust).mean(), name='DI-')
                return pd.concat([diplus, diminus], axis=1)

            @classmethod
            def ADX(cls, ohlc: DataFrame, period: int=14, adjust: bool=True) -> Series:
                dmi = cls.DMI(ohlc, period)
                return pd.Series(100 * (abs(dmi['DI+'] - dmi['DI-']) / (dmi['DI+'] + dmi['DI-'])).ewm(alpha=1 / period, adjust=adjust).mean(), name='{0} period ADX.'.format(period))

            @classmethod
            def STOCH(cls, ohlc: DataFrame, period: int=14) -> Series:
                highest_high = ohlc['high'].rolling(center=False, window=period).max()
                lowest_low = ohlc['low'].rolling(center=False, window=period).min()
                STOCH = pd.Series((ohlc['close'] - lowest_low) / (highest_high - lowest_low) * 100, name='{0} period STOCH %K'.format(period))
                return STOCH

            @classmethod
            def STOCHD(cls, ohlc: DataFrame, period: int=3, stoch_period: int=14) -> Series:
                return pd.Series(cls.STOCH(ohlc, stoch_period).rolling(center=False, window=period).mean(), name='{0} period STOCH %D.'.format(period))

            @classmethod
            def UO(cls, ohlc: DataFrame, column: str='close') -> Series:
                k = []
                for (row, _row) in zip(ohlc.itertuples(), ohlc.shift(1).itertuples()):
                    k.append(min(row.low, _row.close))
                bp = pd.Series(ohlc[column] - k, name='bp')
                Average7 = bp.rolling(window=7).sum() / cls.TR(ohlc).rolling(window=7).sum()
                Average14 = bp.rolling(window=14).sum() / cls.TR(ohlc).rolling(window=14).sum()
                Average28 = bp.rolling(window=28).sum() / cls.TR(ohlc).rolling(window=28).sum()
                return pd.Series(100 * (4 * Average7 + 2 * Average14 + Average28) / (4 + 2 + 1))

            @classmethod
            def MI(cls, ohlc: DataFrame, period: int=9, adjust: bool=True) -> Series:
                _range = pd.Series(ohlc['high'] - ohlc['low'], name='range')
                EMA9 = _range.ewm(span=period, ignore_na=False, adjust=adjust).mean()
                DEMA9 = EMA9.ewm(span=period, ignore_na=False, adjust=adjust).mean()
                mass = EMA9 / DEMA9
                return pd.Series(mass.rolling(window=25).sum(), name='Mass Index')

            @classmethod
            def TP(cls, ohlc: DataFrame) -> Series:
                return pd.Series((ohlc['high'] + ohlc['low'] + ohlc['close']) / 3, name='TP')

            @classmethod
            def ADL(cls, ohlcv: DataFrame) -> Series:
                MFM = pd.Series((ohlcv['close'] - ohlcv['low'] - (ohlcv['high'] - ohlcv['close'])) / (ohlcv['high'] - ohlcv['low']), name='MFM')
                MFV = pd.Series(MFM * ohlcv['volume'], name='MFV')
                return MFV.cumsum()

            @classmethod
            def CHAIKIN(cls, ohlcv: DataFrame, adjust: bool=True) -> Series:
                return pd.Series(cls.ADL(ohlcv).ewm(span=3, min_periods=2, adjust=adjust).mean() - cls.ADL(ohlcv).ewm(span=10, min_periods=9, adjust=adjust).mean())

            @classmethod
            def OBV(cls, ohlcv: DataFrame, column: str='close') -> Series:
                ohlcv['OBV'] = np.nan
                neg_change = ohlcv[column] < ohlcv[column].shift(1)
                pos_change = ohlcv[column] >= ohlcv[column].shift(1)
                no_change = ohlcv[column] == ohlcv[column].shift(1)
                if pos_change.any():
                    ohlcv.loc[pos_change, 'OBV'] = ohlcv['volume']
                if neg_change.any():
                    ohlcv.loc[neg_change, 'OBV'] = -ohlcv['volume']
                if no_change.any():
                    ohlcv.loc[no_change, 'OBV'] = ohlcv['OBV'].shift(1)
                return pd.Series(ohlcv['OBV'].cumsum(), name='OBV')

            @classmethod
            def WOBV(cls, ohlcv: DataFrame, column: str='close') -> Series:
                wobv = pd.Series(ohlcv['volume'] * ohlcv[column].diff(), name='WOBV')
                return wobv.cumsum()

            @classmethod
            def VZO(cls, ohlc: DataFrame, period: int=14, column: str='close', adjust: bool=True) -> Series:
                sign = lambda a: (a > 0) - (a < 0)
                r = ohlc[column].diff().apply(sign) * ohlc['volume']
                dvma = r.ewm(span=period, adjust=adjust).mean()
                vma = ohlc['volume'].ewm(span=period, adjust=adjust).mean()
                return pd.Series(100 * (dvma / vma), name='VZO')

            @classmethod
            def PZO(cls, ohlc: DataFrame, period: int=14, column: str='close', adjust: bool=True) -> Series:
                sign = lambda a: (a > 0) - (a < 0)
                r = ohlc[column].diff().apply(sign) * ohlc[column]
                cp = pd.Series(r.ewm(span=period, adjust=adjust).mean())
                tc = cls.EMA(ohlc, period)
                return pd.Series(100 * (cp / tc), name='{} period PZO'.format(period))

            @classmethod
            def EFI(cls, ohlcv: DataFrame, period: int=13, column: str='close', adjust: bool=True) -> Series:
                fi = pd.Series(ohlcv[column].diff() * ohlcv['volume'])
                return pd.Series(fi.ewm(ignore_na=False, span=period, adjust=adjust).mean(), name='{0} period Force Index'.format(period))

            @classmethod
            def CFI(cls, ohlcv: DataFrame, column: str='close', adjust: bool=True) -> Series:
                fi1 = pd.Series(ohlcv['volume'] * ohlcv[column].diff())
                cfi = pd.Series(fi1.ewm(ignore_na=False, min_periods=9, span=10, adjust=adjust).mean(), name='CFI')
                return cfi.cumsum()

            @classmethod
            def EMV(cls, ohlcv: Series, period: int=14) -> Series:
                distance = pd.Series((ohlcv['high'] + ohlcv['low']) / 2 - (ohlcv['high'].shift() + ohlcv['low'].shift()) / 2)
                box_ratio = pd.Series(ohlcv['volume'] / 1000000 / (ohlcv['high'] - ohlcv['low']))
                _emv = pd.Series(distance / box_ratio)
                return pd.Series(_emv.rolling(window=period).mean(), name='{0} period EMV.'.format(period))

            @classmethod
            def COPP(cls, ohlc: DataFrame, adjust: bool=True) -> Series:
                roc1 = cls.ROC(ohlc, 14)
                roc2 = cls.ROC(ohlc, 11)
                return pd.Series((roc1 + roc2).ewm(span=10, min_periods=9, adjust=adjust).mean(), name='Coppock Curve')

            @classmethod
            def CMO(cls, ohlc: DataFrame, period: int=9, factor: int=100, column: str='close', adjust: bool=True) -> DataFrame:
                delta = ohlc[column].diff()
                (up, down) = (delta.copy(), delta.copy())
                up[up < 0] = 0
                down[down > 0] = 0
                _gain = up.ewm(com=period, adjust=adjust).mean()
                _loss = down.ewm(com=period, adjust=adjust).mean().abs()
                return pd.Series(factor * ((_gain - _loss) / (_gain + _loss)), name='CMO')

