            def WAVEPM(cls, ohlc: DataFrame, period: int=14, lookback_period: int=100, column: str='close') -> Series:
                ma = ohlc[column].rolling(window=period).mean()
                std = ohlc[column].rolling(window=period).std(ddof=0)

