    def _build_kernel_0d9a26ca22a621b2():
        import numpy as np
        import pandas as pd
        from pandas import DataFrame, Series

        class TA:

            @classmethod
            def DMI(cls, ohlc: DataFrame, period: int=14, adjust: bool=True) -> DataFrame:
                ohlc['up_move'] = ohlc['high'].diff()
                ohlc['down_move'] = -ohlc['low'].diff()

                def _dmp(row):
                    if row['up_move'] > row['down_move'] and row['up_move'] > 0:
                        return row['up_move']
                    else:
                        return 0

                def _dmn(row):
                    if row['down_move'] > row['up_move'] and row['down_move'] > 0:
                        return row['down_move']
                    else:
                        return 0
                ohlc['plus'] = ohlc.apply(_dmp, axis=1)
                ohlc['minus'] = ohlc.apply(_dmn, axis=1)
                diplus = pd.Series(100 * (ohlc['plus'] / cls.ATR(ohlc, period)).ewm(alpha=1 / period, adjust=adjust).mean(), name='DI+')
                diminus = pd.Series(100 * (ohlc['minus'] / cls.ATR(ohlc, period)).ewm(alpha=1 / period, adjust=adjust).mean(), name='DI-')
                return pd.concat([diplus, diminus], axis=1)

            @classmethod
            def ATR(cls, ohlc: DataFrame, period: int=14) -> Series:
                TR = cls.TR(ohlc)
                return pd.Series(TR.rolling(center=False, window=period).mean(), name='{0} period ATR'.format(period))

            @classmethod
            def TR(cls, ohlc: DataFrame) -> Series:
                TR1 = pd.Series(ohlc['high'] - ohlc['low']).abs()
                TR2 = pd.Series(ohlc['high'] - ohlc['close'].shift()).abs()
                TR3 = pd.Series(ohlc['close'].shift() - ohlc['low']).abs()
                _TR = pd.concat([TR1, TR2, TR3], axis=1)
                _TR['TR'] = _TR.max(axis=1)
                return pd.Series(_TR['TR'], name='TR')
        return _KernelNamespace(**locals())


    def _build_kernel_0ddb77214ace39ae():
        import numpy as np
        import pandas as pd
        from pandas import DataFrame, Series

        class TA:

            @classmethod
            def BASP(cls, ohlc: DataFrame, period: int=40, adjust: bool=True) -> DataFrame:
                sp = ohlc['high'] - ohlc['close']
                bp = ohlc['close'] - ohlc['low']
                spavg = sp.ewm(span=period, adjust=adjust).mean()
                bpavg = bp.ewm(span=period, adjust=adjust).mean()
                nbp = bp / bpavg
                nsp = sp / spavg
                varg = ohlc['volume'].ewm(span=period, adjust=adjust).mean()
                nv = ohlc['volume'] / varg
                nbfraw = pd.Series(nbp * nv, name='Buy.')
                nsfraw = pd.Series(nsp * nv, name='Sell.')
                return pd.concat([nbfraw, nsfraw], axis=1)
        return _KernelNamespace(**locals())


    def _build_kernel_0e3fbba1da15bc25():
        import numpy as np
        import pandas as pd
        from pandas import DataFrame, Series

        class TA:

            @classmethod
            def MACD(cls, ohlc: DataFrame, period_fast: int=12, period_slow: int=26, signal: int=9, column: str='close', adjust: bool=True) -> DataFrame:
                EMA_fast = pd.Series(ohlc[column].ewm(ignore_na=False, span=period_fast, adjust=adjust).mean(), name='EMA_fast')
                EMA_slow = pd.Series(ohlc[column].ewm(ignore_na=False, span=period_slow, adjust=adjust).mean(), name='EMA_slow')
                MACD = pd.Series(EMA_fast - EMA_slow, name='MACD')
                MACD_signal = pd.Series(MACD.ewm(ignore_na=False, span=signal, adjust=adjust).mean(), name='SIGNAL')
                return pd.concat([MACD, MACD_signal], axis=1)
        return _KernelNamespace(**locals())


