        import numpy as np
        import pandas as pd
        from pandas import DataFrame, Series

        class TA:

            @classmethod
            def PIVOT_FIB(cls, ohlc: DataFrame) -> DataFrame:
                df = ohlc.shift()
                pp = pd.Series(cls.TP(df), name='pivot')
                r4 = pp + (df['high'] - df['low']) * 1.382
                r3 = pp + (df['high'] - df['low']) * 1
                r2 = pp + (df['high'] - df['low']) * 0.618
                r1 = pp + (df['high'] - df['low']) * 0.382
                s1 = pp - (df['high'] - df['low']) * 0.382
                s2 = pp - (df['high'] - df['low']) * 0.618
                s3 = pp - (df['high'] - df['low']) * 1
                s4 = pp - (df['high'] - df['low']) * 1.382
                return pd.concat([pp, pd.Series(s1, name='s1'), pd.Series(s2, name='s2'), pd.Series(s3, name='s3'), pd.Series(s4, name='s4'), pd.Series(r1, name='r1'), pd.Series(r2, name='r2'), pd.Series(r3, name='r3'), pd.Series(r4, name='r4')], axis=1)

            @classmethod
            def TP(cls, ohlc: DataFrame) -> Series:
                return pd.Series((ohlc['high'] + ohlc['low'] + ohlc['close']) / 3, name='TP')
        return _KernelNamespace(**locals())


