        import numpy as np
        import pandas as pd
        from pandas import DataFrame, Series

        class TA:

            @classmethod
            def WTO(cls, ohlc: DataFrame, channel_length: int=10, average_length: int=21, adjust: bool=True) -> DataFrame:
                ap = cls.TP(ohlc)
                esa = ap.ewm(span=average_length, adjust=adjust).mean()
                d = pd.Series((ap - esa).abs().ewm(span=channel_length, adjust=adjust).mean(), name='d')
                ci = (ap - esa) / (0.015 * d)
                wt1 = pd.Series(ci.ewm(span=average_length, adjust=adjust).mean(), name='WT1.')
                wt2 = pd.Series(wt1.rolling(window=4).mean(), name='WT2.')
                return pd.concat([wt1, wt2], axis=1)

            @classmethod
            def TP(cls, ohlc: DataFrame) -> Series:
                return pd.Series((ohlc['high'] + ohlc['low'] + ohlc['close']) / 3, name='TP')
        return _KernelNamespace(**locals())


