        import numpy as np
        import pandas as pd
        from pandas import DataFrame, Series

        class TA:

            @classmethod
            def PIVOT(cls, ohlc: DataFrame) -> DataFrame:
                df = ohlc.shift()
                pivot = pd.Series(cls.TP(df), name='pivot')
                s1 = pivot * 2 - df['high']
                s2 = pivot - (df['high'] - df['low'])
                s3 = df['low'] - 2 * (df['high'] - pivot)
                s4 = df['low'] - 3 * (df['high'] - pivot)
                r1 = pivot * 2 - df['low']
                r2 = pivot + (df['high'] - df['low'])
                r3 = df['high'] + 2 * (pivot - df['low'])
                r4 = df['high'] + 3 * (pivot - df['low'])
                return pd.concat([pivot, pd.Series(s1, name='s1'), pd.Series(s2, name='s2'), pd.Series(s3, name='s3'), pd.Series(s4, name='s4'), pd.Series(r1, name='r1'), pd.Series(r2, name='r2'), pd.Series(r3, name='r3'), pd.Series(r4, name='r4')], axis=1)

            @classmethod
            def TP(cls, ohlc: DataFrame) -> Series:
                return pd.Series((ohlc['high'] + ohlc['low'] + ohlc['close']) / 3, name='TP')
        return _KernelNamespace(**locals())


