        from pandas import DataFrame, Series

        class TA:

            @classmethod
            def STOCHRSI(cls, ohlc: DataFrame, rsi_period: int=14, stoch_period: int=14) -> Series:
                rsi = cls.RSI(ohlc, rsi_period)
                lo = rsi.rolling(stoch_period, min_periods=stoch_period).min()
                hi = rsi.rolling(stoch_period, min_periods=stoch_period).max()
                return ((rsi - lo) / (hi - lo)).rolling(stoch_period, min_periods=stoch_period).mean()

            @classmethod
            def RSI(cls, ohlc: DataFrame, period: int=14, column: str='close', adjust: bool=True) -> Series:
                delta = ohlc[column].diff()
                (up, down) = (delta.copy(), delta.copy())
                up[up < 0] = 0
                down[down > 0] = 0
                _gain = up.ewm(alpha=1.0 / period, adjust=adjust).mean()
                _loss = down.abs().ewm(alpha=1.0 / period, adjust=adjust).mean()
                RS = _gain / _loss
                return pd.Series(100 - 100 / (1 + RS), name='{0} period RSI'.format(period))
        return _KernelNamespace(**locals())


