        import numpy as np
        import pandas as pd
        from pandas import DataFrame, Series

        class TA:

            @classmethod
            def VW_MACD(cls, ohlcv: DataFrame, period_fast: int=12, period_slow: int=26, signal: int=9, column: str='close', adjust: bool=True) -> DataFrame:
                vp = ohlcv['volume'] * ohlcv[column]
                _fast = pd.Series(vp.ewm(ignore_na=False, span=period_fast, adjust=adjust).mean() / ohlcv['volume'].ewm(ignore_na=False, span=period_fast, adjust=adjust).mean(), name='_fast')
                _slow = pd.Series(vp.ewm(ignore_na=False, span=period_slow, adjust=adjust).mean() / ohlcv['volume'].ewm(ignore_na=False, span=period_slow, adjust=adjust).mean(), name='_slow')
                MACD = pd.Series(_fast - _slow, name='MACD')
                MACD_signal = pd.Series(MACD.ewm(ignore_na=False, span=signal, adjust=adjust).mean(), name='SIGNAL')
                return pd.concat([MACD, MACD_signal], axis=1)
        return _KernelNamespace(**locals())


