    def _build_kernel_88a7fe4bc1b27067():
        import numpy as np
        import pandas as pd
        from pandas import DataFrame, Series

        class TA:

            @classmethod
            def EV_MACD(cls, ohlcv: DataFrame, period_fast: int=20, period_slow: int=40, signal: int=9, adjust: bool=True) -> DataFrame:
                evwma_slow = cls.EVWMA(ohlcv, period_slow)
                evwma_fast = cls.EVWMA(ohlcv, period_fast)
                MACD = pd.Series(evwma_fast - evwma_slow, name='MACD')
                MACD_signal = pd.Series(MACD.ewm(ignore_na=False, span=signal, adjust=adjust).mean(), name='SIGNAL')
                return pd.concat([MACD, MACD_signal], axis=1)

            @classmethod
            def EVWMA(cls, ohlcv: DataFrame, period: int=20) -> Series:
                vol_sum = ohlcv['volume'].rolling(window=period).sum()
                x = (vol_sum - ohlcv['volume']) / vol_sum
                y = ohlcv['volume'] * ohlcv['close'] / vol_sum
                evwma = [0]
                for (x, y) in zip(x.fillna(0).items(), y.items()):
                    if x[1] == 0 or y[1] == 0:
                        evwma.append(0)
                    else:
                        evwma.append(evwma[-1] * x[1] + y[1])
                return pd.Series(evwma[1:], index=ohlcv.index, name='{0} period EVWMA.'.format(period))
        return _KernelNamespace(**locals())


