_formula_calculations = _create_formula_calculations()
_technical_calculations = _create_technical_calculations()

PRICE_FIELDS = {'open_hfq', 'high_hfq', 'low_hfq', 'close_hfq', 'open', 'high', 'low', 'close'}

def panels(data, fields):
    dates = pd.DatetimeIndex(data.index.get_level_values('date').unique()).sort_values()
    symbols = data.index.get_level_values('symbol').unique().sort_values()
    out = {}
    for field in fields:
        if field.startswith('industry_sw_'):
            out[field] = data[field].unstack('symbol').reindex(index=dates, columns=symbols).astype('string').replace('', pd.NA)
            continue
        value = pd.to_numeric(data[field], errors='coerce').astype(float).unstack('symbol').reindex(index=dates, columns=symbols).replace([np.inf, -np.inf], np.nan)
        if field in PRICE_FIELDS or field in ('adj_factor', 'total_share', 'float_share', 'total_mv', 'circ_mv'):
            value = value.where(value > 0)
        if field in ('vol', 'amount'):
            value = value.where(value >= 0)
        out[field] = value
    (h, l) = (out.get('high_hfq'), out.get('low_hfq'))
    if h is not None and l is not None:
        valid = h >= l
        out['high_hfq'] = h.where(valid)
        out['low_hfq'] = l.where(valid)
    for (bound, compare) in (('high_hfq', lambda a, b: a >= b), ('low_hfq', lambda a, b: a <= b)):
        if bound not in out:
            continue
        for field in ('open_hfq', 'close_hfq'):
            if field in out:
                valid = compare(out[bound], out[field])
                out[bound] = out[bound].where(valid)
                out[field] = out[field].where(valid)
    if {'amount', 'vol', 'adj_factor'} <= out.keys():
        out['P'] = out['amount'] * 10 / out['vol'].where(out['vol'] > 0) * out['adj_factor']
    return (out, dates, symbols)

def eligibility(data, dates, symbols):
    eligible = data['is_member'].unstack('symbol').reindex(index=dates, columns=symbols).astype('boolean').fillna(False).astype(bool)
    for field in ('is_st', 'is_suspended'):
        eligible &= ~data[field].unstack('symbol').reindex(index=dates, columns=symbols).astype('boolean').fillna(False).astype(bool)
    return eligible

def alpha_environment(spec, x, eligible, dates, symbols):
    empty = pd.DataFrame(np.nan, index=dates, columns=symbols)
    env = {'C': x.get('close_hfq', empty), '_eligible': eligible}
    for (key, field) in {'O': 'open_hfq', 'H': 'high_hfq', 'L': 'low_hfq', 'V': 'vol', 'A': 'amount', 'P': 'P', 'MC': 'total_mv', 'BO': 'benchmark_open', 'BC': 'benchmark_close', 'SW1': 'industry_sw_1', 'SW2': 'industry_sw_2', 'SW3': 'industry_sw_3'}.items():
        if field in x:
            env[key] = x[field] * (100 if key == 'V' else 1000 if key == 'A' else 10000 if key == 'MC' else 1) if key not in ('SW1', 'SW2', 'SW3') else x[field]
    variables = set()

    def walk(node):
        if not isinstance(node, (list, tuple)):
            return
        if node[0] == 'var':
            variables.add(node[1])
        for child in node[1:]:
            if isinstance(child, (tuple, list)):
                if child and isinstance(child[0], (tuple, list)):
                    for item in child:
                        walk(item)
                else:
                    walk(child)
    walk(spec['tree'])
    c = env['C']
    h = env.get('H', empty)
    l = env.get('L', empty)
    o = env.get('O', empty)
    for variable in variables:
        if variable in env:
            continue
        if re.fullmatch('adv\\d+', variable, re.I):
            n = int(variable[3:])
            env[variable] = env['A'].rolling(n, min_periods=n).mean()
        elif variable in ('R', 'RET'):
            env[variable] = c / c.shift(1) - 1
        elif variable == 'HD':
            env[variable] = h - h.shift(1)
        elif variable == 'LD':
            env[variable] = l.shift(1) - l
        elif variable == 'TR':
            env[variable] = pd.DataFrame(np.maximum.reduce([(h - l).to_numpy(), (h - c.shift(1)).abs().to_numpy(), (l - c.shift(1)).abs().to_numpy()]), index=dates, columns=symbols)
        elif variable in ('DTM', 'DBM'):
            prev = o.shift(1)
            a = h - o if variable == 'DTM' else o - l
            b = o - prev
            v = pd.DataFrame(np.maximum(a, b), index=dates, columns=symbols)
            env[variable] = v.where(o > prev if variable == 'DTM' else o < prev, 0).mask(o.isna() | prev.isna() | a.isna())
        else:
            raise ValueError(f'未绑定Alpha输入: {variable}')
    return env

class PublicFactor(BaseFactor):
    """逐文件声明输入/固定配方，统一沿框架真实日历输出浮点面板。"""
    PRESERVE_REPORT_HISTORY = True
    warmup_days = 100000
    SPEC: dict = {}
    INPUTS: dict = {}

    def __init__(self):
        pass

    def generate_signals(self, data, constituents=None):
        if data.empty:
            return pd.DataFrame(dtype=float).rename_axis(index='date', columns='symbol')
        spec = self.SPEC
        if spec['engine'] == 'financial':
            return _formula_calculations.calculate_financial(spec, data, self.INPUTS)
        fields = {key for (key, source) in self.INPUTS.items() if not source.announcement_columns}
        if spec['engine'] == 'alpha' and 'BC' in repr(spec['tree']):
            fields.add('benchmark_close')
        (x, dates, symbols) = panels(data, fields)
        eligible = eligibility(data, dates, symbols)
        with np.errstate(all='ignore'):
            if spec['engine'] == 'alpha':
                env = alpha_environment(spec, x, eligible, dates, symbols)
                if 'kernel' in spec:
                    module = _technical_calculations.kernel(spec['kernel'])
                    result = getattr(module, spec['root_function'])(spec['tree'], env)
                else:
                    result = _formula_calculations.evaluate_alpha(
                        spec['tree'], env, spec['kind'],
                        constant_correlation_zero=spec.get('constant_correlation_zero', False))
            elif spec['engine'] == 'market':
                result = _formula_calculations.calculate_market(spec, x, eligible)
            else:
                mapping = {'open_hfq': 'open', 'high_hfq': 'high', 'low_hfq': 'low', 'close_hfq': 'close', 'vol': 'volume', 'amount': 'amount', 'adj_factor': 'adj_factor', 'benchmark_close': 'benchmark', 'open': 'open_unadjusted', 'close': 'close_unadjusted'}
                adapted = {mapping[k]: v * (100 if k == 'vol' else 1000 if k == 'amount' else 1) for (k, v) in x.items() if k in mapping}
                if spec.get('adjust_turnover_price'):
                    adapted['amount'] = adapted['amount'] * adapted['adj_factor']
                result = _technical_calculations.calculate(spec, adapted)
        return result.astype(float).replace([np.inf, -np.inf], np.nan).rename_axis(index='date', columns='symbol')
